macro_rules! deps {
    () => {
        Builder!();
    };
}

macro_rules! TempDir {
    () => {
        deps!();
        # [doc = " A directory in the filesystem that is automatically deleted when"] # [doc = " it goes out of scope."] # [doc = ""] # [doc = " The [`TempDir`] type creates a directory on the file system that"] # [doc = " is deleted once it goes out of scope. At construction, the"] # [doc = " `TempDir` creates a new directory with a randomly generated name."] # [doc = ""] # [doc = " The default constructor, [`TempDir::new()`], creates directories in"] # [doc = " the location returned by [`env::temp_dir()`], but `TempDir`"] # [doc = " can be configured to manage a temporary directory in any location"] # [doc = " by constructing with a [`Builder`]."] # [doc = ""] # [doc = " After creating a `TempDir`, work with the file system by doing"] # [doc = " standard [`std::fs`] file system operations on its [`Path`],"] # [doc = " which can be retrieved with [`TempDir::path()`]. Once the `TempDir`"] # [doc = " value is dropped, the directory at the path will be deleted, along"] # [doc = " with any files and directories it contains. It is your responsibility"] # [doc = " to ensure that no further file system operations are attempted"] # [doc = " inside the temporary directory once it has been deleted."] # [doc = ""] # [doc = " # Resource Leaking"] # [doc = ""] # [doc = " Various platform-specific conditions may cause `TempDir` to fail"] # [doc = " to delete the underlying directory. It's important to ensure that"] # [doc = " handles (like [`File`] and [`ReadDir`]) to files inside the"] # [doc = " directory are dropped before the `TempDir` goes out of scope. The"] # [doc = " `TempDir` destructor will silently ignore any errors in deleting"] # [doc = " the directory; to instead handle errors call [`TempDir::close()`]."] # [doc = ""] # [doc = " Note that if the program exits before the `TempDir` destructor is"] # [doc = " run, such as via [`std::process::exit()`], by segfaulting, or by"] # [doc = " receiving a signal like `SIGINT`, then the temporary directory"] # [doc = " will not be deleted."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Create a temporary directory with a generated name:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::fs::File;"] # [doc = " use std::io::Write;"] # [doc = " use tempfile::TempDir;"] # [doc = ""] # [doc = " // Create a directory inside of `env::temp_dir()`"] # [doc = " let tmp_dir = TempDir::new()?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] # [doc = ""] # [doc = " Create a temporary directory with a prefix in its name:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::fs::File;"] # [doc = " use std::io::Write;"] # [doc = " use tempfile::Builder;"] # [doc = ""] # [doc = " // Create a directory inside of `env::temp_dir()`,"] # [doc = " // whose name will begin with 'example'."] # [doc = " let tmp_dir = Builder::new().prefix(\"example\").tempdir()?;"] # [doc = " # Ok::<(), std::io::Error>(())"] # [doc = " ```"] # [doc = ""] # [doc = " [`File`]: http://doc.rust-lang.org/std/fs/struct.File.html"] # [doc = " [`Path`]: http://doc.rust-lang.org/std/path/struct.Path.html"] # [doc = " [`ReadDir`]: http://doc.rust-lang.org/std/fs/struct.ReadDir.html"] # [doc = " [`Builder`]: struct.Builder.html"] # [doc = " [`TempDir::close()`]: struct.TempDir.html#method.close"] # [doc = " [`TempDir::new()`]: struct.TempDir.html#method.new"] # [doc = " [`TempDir::path()`]: struct.TempDir.html#method.path"] # [doc = " [`TempDir`]: struct.TempDir.html"] # [doc = " [`std::fs`]: http://doc.rust-lang.org/std/fs/index.html"] # [doc = " [`std::process::exit()`]: http://doc.rust-lang.org/std/process/fn.exit.html"] pub struct TempDir { path : Box < Path > , disable_cleanup : bool , }
    };
}

TempDir!();